class Solution:
    def getMinMaxParcels(self, parcels: List[int], extraParcels: int) -> int:
        lo, hi = max(parcels), max(parcels) + extraParcels
        def room(L):
            s = 0
            for p in parcels:
                if p < L:
                    s += L - p
                    if s >= extraParcels:
                        return s
            return s
        while lo < hi:
            mid = (lo + hi) // 2
            if room(mid) >= extraParcels:
                hi = mid
            else:
                lo = mid + 1
        return lo

